"""Reusable authoring fragments, shared by all published demo entry points."""
from ui import UI,bind
item=lambda key:{'item':'/'+key}
T=lambda name:'calliope_apps.demo_'+name

def add_pages(doc,PAGES,TECHS):
    F,R,W=doc['fragments'],doc['repeat'],doc['switch']
    def fragment(name,u,children,**kw):
        root=u.stack('body',children,**kw);F[name]={'root':root,'components':u.nodes};return name
    def rows(u,id,path,name,weight=None):
        R[id]={'path':path,'fragment':name,'key':'id'}
        return u.stack(id,[],**({'weight':weight} if weight else {}))
    def slot(u,id,path,cases,default=None):
        W[id]={'path':path,'cases':cases,'default':default}
        return u.stack(id,[])
    def hero(u,tag,title,copy):return u.stack('identity',[u.text('eyebrow',tag,'eyebrow','muted'),u.text('heading',title,'display',family='display'),u.text('purpose',copy,'body','muted')],gap='sm')
    def identity(form):return {'id':bind('/state/'+form+'/id'),'version':bind('/state/'+form+'/version')}
    def form_action(u,id,label,event,form,fields=(),primary=True):return u.button(id,label,event,{**identity(form),**{field:bind('/state/'+form+'/'+field) for field in fields}},primary)
    def filters(u,kind):
        fields=[]
        if kind=='deals':fields.append(u.picker('owner-filter','Owner','/state/filter/owner',[(v,v) for v in ['Everyone','Alex Morgan','Sam Rivera']]))
        elif kind=='visits':
            fields=[u.picker('technician-filter','Technician','/state/filter/technician',[(v,v) for v in ['Everyone',*TECHS]]),u.picker('days-filter','Period','/state/filter/days',[(v,v+' days') for v in ['7','28','56','365']]),u.picker('status-filter','Status','/state/filter/status',[(v,v) for v in ['All','Scheduled','Dispatched','On site','Complete']]),u.field('search-filter','Search visits','/state/filter/search')]
        elif kind=='schedule':fields=[u.field('day-filter','Schedule date','/state/filter/date','date',required=True)]
        else:fields=[u.field('search-filter','Search purchase orders','/state/filter/search')]
        return u.filters('filters','Find work','/state/filter','filter',fields)
    def selected_visit(u):return u.stack('visit-heading',[u.text('customer',bind('/job/customer'),'title',family='display'),u.text('address',bind('/job/address'),'caption','muted'),u.badge('status',bind('/job/status'),'cool'),u.text('equipment',bind('/job/equipment'),'caption','muted'),u.text('parts',bind('/job/parts'),'caption','warm')],gap='sm')
    def log(u):return u.section('activity-section','What changed',[rows(u,'activity-list','/activity','activity-row')],subtitle='Committed work across the shared data.')

    u=UI();fragment('deal-row',u,[u.badge('stage',item('stage'),'cool'),u.button('open',item('address'),'select_deal',{'id':item('id')}),u.text('buyer',item('buyer'),'caption','muted'),u.text('price',item('price_label'),'title',family='mono'),u.text('closing',item('closing_date'),'caption','muted')],gap='sm')
    u=UI();fragment('job-row',u,[u.badge('status',item('status'),'cool'),u.button('open',item('customer'),'select_job',{'id':item('id')}),u.text('detail',item('detail'),'caption','muted')],gap='sm')
    u=UI();fragment('task-row',u,[u.text('title',item('title')),u.text('due',item('due'),'caption','muted'),u.badge('status',item('label'),'cool'),u.button('complete','Mark complete','complete_task',{**identity('dealForm'),'task':item('id')})],gap='sm')
    u=UI();fragment('activity-row',u,[u.text('date',item('created'),'caption','muted'),u.text('description',item('description'))],gap='xs')
    u=UI();fragment('quote-row',u,[u.button('open',item('id'),'select_quote',{'id':item('id')}),u.text('customer',item('customer_id'),'caption','muted'),u.badge('status',item('status'),'cool')],gap='sm')
    u=UI();fragment('product-row',u,[u.text('part',item('name')),u.text('price',item('price_label'),'caption','muted')],gap='xs')
    u=UI();fragment('po-row',u,[u.button('open',item('id'),'select_po',{'id':item('id')}),u.text('detail',item('detail'),'caption','muted')],gap='sm')
    u=UI();fragment('report-row',u,[u.badge('id',item('id'),'success'),u.text('detail',item('detail'),'caption','muted'),u.text('notes',item('notes')),u.text('temperature',item('temperature'),'caption'),u.text('pressure',item('pressure'),'caption'),u.text('correction',item('correction_of'),'caption','muted'),u.add('files','CAttachments',label='Evidence',value=item('attachments'),names=bind('/attachmentNames'),readOnly=True)])
    u=UI();fragment('equipment-row',u,[u.text('name',item('name'),'title',family='display'),u.text('identity',item('identity'),'caption','muted'),u.text('location',item('location')),u.text('notes',item('service_notes'),'caption','muted')])

    # The real-estate layouts share the record and commitments without freezing them.
    u=UI();fragment('deal-editor',u,[u.text('address',bind('/deal/address'),'title',family='display'),u.text('buyer',bind('/deal/buyer')),u.text('price',bind('/deal/price_label'),'metric','accent',family='mono'),u.field('notes','Working notes','/state/dealForm/notes','longText',maxLength=4000),u.picker('owner','Owner','/state/dealForm/owner',[(v,v) for v in TECHS[:2]]),u.field('closing','Target close','/state/dealForm/closing_date','date'),u.stack('actions',[u.button('save','Save transaction','save_deal',{**identity('dealForm'),'notes':bind('/state/dealForm/notes'),'owner':bind('/state/dealForm/owner/0'),'date':bind('/state/dealForm/closing_date')},True),form_action(u,'advance','Advance stage','advance_deal','dealForm'),u.button('discard','Discard edits','discard')],'row','sm',wrap=True)])
    for page,title,copy in [('dossier','Keep the whole transaction together.','The client, the next commitment, and the working file.'),('pipeline','See what is moving.','A live pipeline of clients, value, and closing commitments.'),('briefing','Start with what needs you.','A short briefing built from the same transaction records.')]:
        u=UI();head=hero(u,'TRANSACTION DESK / '+page.upper(),title,copy)
        listing=u.section('transactions','Transactions',[rows(u,'deal-list','/deals','deal-row')],weight=2)
        editor=u.section('working','Working file',[slot(u,'deal-editor-slot','/state/page',{p:'deal-editor' for p in ('dossier','pipeline','briefing')})],tone='accent',weight=3)
        tasks=u.section('commitments','Commitments',[rows(u,'task-list','/tasks','task-row')],weight=2)
        chart=u.add('pipeline-chart','CVegaChart',spec=bind('/charts/pipeline'),height=260,description='Transaction value by stage')
        content=[head,filters(u,'deals')]
        if page=='dossier':content+=[u.stack('work',[listing,editor,tasks],'row','lg','tablet')]
        elif page=='pipeline':content+=[u.section('pipeline','Pipeline value',[chart],tone='cool'),u.stack('work',[listing,editor,tasks],'row','lg','tablet')]
        else:content+=[u.stack('overview',[u.section('value','The shape of the pipeline',[chart],weight=2),tasks],'row','lg','tablet'),u.stack('work',[listing,editor],'row','lg','tablet')]
        # Drop unused chart node in the dossier composition.
        if page=='dossier':u.nodes=[n for n in u.nodes if n['id']!='pipeline-chart']
        fragment(page,u,content,gap='lg')

    u=UI();fragment('visit-editor',u,[selected_visit(u),u.field('visit-notes','Visit notes','/state/jobForm/notes','longText',maxLength=4000),u.stack('actions',[form_action(u,'save','Save notes','save_job','jobForm',['notes']),form_action(u,'advance','Advance visit','advance_job','jobForm'),u.button('field','Field notebook','page_field'),u.button('schedule','Plan appointment','page_dispatch')],'row','sm',wrap=True)])
    u=UI();chart_panels=[]
    for key,title in [('status','Work in motion'),('revenue','The shape of the month'),('mix','Where the work lands')]:
        chart_panels.append(u.section('chart-'+key,title,[u.add(key,'CVegaChart',spec=bind('/charts/'+key),height=260,description=title,**({'onSelect':'chart_status'} if key=='status' else {}))],weight=1))
    fragment('hvac',u,[hero(u,'NORTHSTAR SERVICE / OPERATIONS','A clearer day in the field.','Visits, customer context, and the work behind the numbers.'),filters(u,'visits'),u.stack('charts',chart_panels,'row','md','tablet'),u.stack('work',[u.section('queue','Visit work list',[rows(u,'job-list','/jobs','job-row')],weight=2),u.section('working','Visit workspace',[slot(u,'visit-editor-slot','/state/page',{'hvac':'visit-editor'})],tone='accent',weight=3)],'row','lg','tablet'),log(u)],gap='lg')

    # Quote lines are generated from SQL rows and edit the matching form keys.
    u=UI();fragment('quote-line',u,[u.text('name',item('name')),u.add('quantity','CField',label='Quantity',value={'path':item('quantity_path')},kind='quantity',minimum='0.01',maximum='10000',precision=2),u.add('price','CField',label='Unit price',value={'path':item('price_path')},kind='money',minimum='0',precision=2),u.button('remove','Remove','remove_part',{'draft':bind('/state/quoteForm'),'line':item('id')})])
    u=UI();grid=u.add('quote-lines','CDataGrid',columns=[{'label':x} for x in ('Part','Quantity','Unit price','')],children=[],rowKeys=[]);R['quote-lines']={'path':'/quoteLines','fragment':'quote-line','key':'id'}
    quote_editor=u.section('quote-editor','Working quote',[u.text('quote-id',bind('/quote/id'),'title',family='mono'),u.badge('quote-status',bind('/quote/status'),'cool'),u.picker('branch','Branch','/state/quoteForm/branch',[('north','North branch'),('south','South depot')]),grid,u.field('quote-notes','Quote notes','/state/quoteForm/notes','longText'),u.text('total',bind('/quote/total_label'),'metric','accent',family='mono'),u.stack('quote-actions',[u.button('save','Save quote','save_quote',{'draft':bind('/state/quoteForm')},True),u.button('new','New quote','new_quote')],'row','sm'),u.picker('product','Catalog part','/state/controls/product',[(x,x) for x in ['CAP-45-5','CONTACTOR-2P','FILTER-20','TSTAT-PRO','TUBE-38','MOTOR-ECM','HP-3T','KIT-DRAIN']]),u.button('add','Add selected part','add_part',{'draft':bind('/state/quoteForm'),'product':bind('/state/controls/product/0')}),u.add('backorder','CheckBox',label='Reserve available stock and backorder any shortage',value=bind('/state/controls/allow_backorder')),u.button('order','Create order & reserve','order_quote',{'draft':bind('/state/quoteForm'),'allow':bind('/state/controls/allow_backorder')},True),u.text('order-id',bind('/quote/order_id'),'caption','muted'),u.button('visit','Create linked service visit','create_visit',{'quote':bind('/quote/id')})],tone='accent',weight=3)
    fragment('counter',u,[hero(u,'NORTHSTAR / PARTS DESK','Get the right parts moving.','Quote, reserve, backorder, and connect the service visit.'),u.stack('work',[u.section('quotes','Quotes',[rows(u,'quote-list','/quotes','quote-row')],weight=1),quote_editor],'row','lg','tablet')],gap='lg')

    u=UI();fragment('receipt-line',u,[u.text('name',item('name')),u.text('remaining',item('remaining'),'caption','muted'),u.add('quantity','CField',label='Usable quantity received',value={'path':item('quantity_path')},kind='quantity',minimum='0',maximum=item('remaining'),precision=2)])
    u=UI();fragment('receipt-review',u,[u.text('title','Before stock changes.','title',family='display'),u.text('reference',bind('/state/receiptReview/reference')),u.text('date',bind('/state/receiptReview/received_date')),u.text('copy','Confirming posts an immutable receipt and allocates usable stock to waiting orders, oldest first.'),u.button('confirm','Confirm & post delivery','receive',primary=True)])
    u=UI();fragment('receipt-editor',u,[u.text('po',bind('/po/id'),'title',family='mono'),u.text('supplier',bind('/po/supplier')),u.stack('when',[u.field('date','Received date','/state/receiptForm/received_date','date',required=True),u.field('time','Time','/state/receiptForm/received_time','time',required=True)],'row','sm'),u.field('reference','Delivery reference','/state/receiptForm/reference',required=True,maxLength=100),rows(u,'receipt-lines','/poLines','receipt-line'),u.field('notes','Delivery notes','/state/receiptForm/notes','longText'),u.button('review','Review delivery','review_receive',{'draft':bind('/state/receiptForm')},True),slot(u,'receipt-review-slot','/state/controls/review',{'receipt':'receipt-review'})])
    u=UI();fragment('receiving',u,[hero(u,'NORTHSTAR / RECEIVING','Turn a delivery into readiness.','Receipts, reservations, and waiting work use the same SQL records.'),filters(u,'receiving'),u.stack('work',[u.section('queue','Expected deliveries',[rows(u,'po-list','/purchaseOrders','po-row')],weight=2),u.section('delivery','Receive a delivery',[slot(u,'receipt-slot','/state/page',{'receiving':'receipt-editor'})],tone='warm',weight=3)],'row','lg','tablet'),log(u)],gap='lg')

    u=UI();fragment('schedule-review',u,[u.text('title','A deliberate handoff.','title',family='display'),u.text('before-date',bind('/job/scheduled_date')),u.text('after-date',bind('/state/scheduleReview/scheduled_date')),u.text('after-start',bind('/state/scheduleReview/start')),u.text('after-end',bind('/state/scheduleReview/end')),u.text('reason',bind('/state/scheduleReview/reason')),u.button('confirm','Confirm reviewed appointment','schedule',primary=True)])
    u=UI();fragment('schedule-editor',u,[selected_visit(u),u.field('date','Visit date','/state/scheduleForm/scheduled_date','date',required=True),u.picker('technician','Assigned technician','/state/scheduleForm/technician',[(v,v) for v in TECHS]),u.stack('times',[u.field('start','Starts','/state/scheduleForm/start','time',required=True),u.field('end','Ends','/state/scheduleForm/end','time',required=True)],'row','sm'),u.field('reason','Reason / visit plan','/state/scheduleForm/reason',required=True,maxLength=500),u.button('review','Review schedule change','review_schedule',{'draft':bind('/state/scheduleForm')},True),slot(u,'schedule-review-slot','/state/controls/review',{'schedule':'schedule-review'}),form_action(u,'release','Release / advance visit','advance_job','jobForm')])
    u=UI();fragment('timeline-row',u,[u.button('open',item('customer'),'select_job',{'id':item('id')}),u.text('time',item('slot'),'caption'),u.badge('status',item('status'),'cool')],gap='xs')
    doc['data']['timeline']={'rows':[],'positions':[]}
    doc['queries']['timeline']={'sql':f"""WITH slots AS (SELECT j.id,j.customer,j.slot,j.status,CASE j.technician WHEN 'Alex Morgan' THEN 0 WHEN 'Sam Rivera' THEN 1 ELSE 2 END lane,
      (extract(epoch FROM s.start::time)/60)::integer start,(extract(epoch FROM s.\"end\"::time)/60)::integer \"end\"
      FROM {T('hvac_jobs')} j JOIN {T('dispatch_slots')} s ON s.job_id=j.id WHERE j.scheduled_date=$1 AND j.status<>'Complete' ORDER BY j.technician,s.start)
      SELECT jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(slots)),'[]'::jsonb),'positions',coalesce(jsonb_agg(jsonb_build_object('lane',lane,'start',start,'end',\"end\")),'[]'::jsonb)) AS timeline FROM slots""",'params':[bind('/state/filter/date')],'path':'/timeline','shape':'value'}
    u=UI();timeline=u.add('day','CResourceDay',children=[],resources=TECHS,positions=bind('/timeline/positions'),start=360,end=1200,label='Technician day plan');R['day']={'path':'/timeline/rows','fragment':'timeline-row','key':'id'}
    fragment('dispatch',u,[hero(u,'NORTHSTAR SERVICE / DISPATCH','Make room for the work.','Review assignments against parts readiness and existing appointments.'),filters(u,'schedule'),u.section('day-plan','The day ahead',[timeline],tone='cool'),u.stack('work',[u.section('queue','Visits to plan',[rows(u,'dispatch-jobs','/jobs','job-row')],weight=2),u.section('appointment','Appointment review',[slot(u,'schedule-slot','/state/page',{'dispatch':'schedule-editor'})],tone='accent',weight=3)],'row','lg','tablet'),log(u)],gap='lg')

    u=UI();editor=u.section('report','Record your findings',[selected_visit(u),u.field('notes','What did you find?','/state/fieldForm/notes','longText',required=True,maxLength=4000),u.stack('readings',[u.field('temperature','Temperature °C','/state/fieldForm/temperature','quantity',minimum='-50',maximum='150',precision=1),u.field('pressure','Pressure psi','/state/fieldForm/pressure','quantity',minimum='0',maximum='1000',precision=1)],'row','sm'),u.field('correction','Corrects report ID (optional)','/state/fieldForm/correction_of'),u.add('evidence','CAttachments',label='Photos and documents',value=bind('/state/fieldForm/attachments'),names=bind('/attachmentNames')),u.button('submit','Submit report','submit_report',primary=True),u.text('scope','Reports are appended in Calliope. Submitting a report does not change the visit status.','caption','muted')],tone='accent',weight=3)
    fragment('field',u,[hero(u,'NORTHSTAR SERVICE / FIELD NOTEBOOK','Leave a useful record.','Findings and readings stay connected to the service visit.'),filters(u,'visits'),u.stack('work',[u.section('visits','Visits',[rows(u,'field-jobs','/jobs','job-row')],weight=2),editor,u.section('reports','Submitted reports',[rows(u,'report-list','/reports','report-row')],weight=2)],'row','lg','tablet')],gap='lg')

    for label,title,copy,tone in [('diagnose','Make the symptom concrete.','Record when the symptom appears and compare it with the equipment history.','cool'),('parts','Bring the right part.','Verify model and rotation, inspect reservations, and follow the delivery.','accent'),('comeback','Pick up the whole story.','Compare the earlier repair with the returning symptom before choosing the next step.','warm'),('clarify','A little more context.','Describe what changed, what is confirmed, and whether this repeats a recent repair.','neutral')]:
        u=UI();fragment('next-'+label,u,[u.panel('suggestion',[u.badge('label',label.upper(),tone),u.text('title',title,'title',family='display'),u.text('copy',copy)],tone,'wash')])
    u=UI();fragment('adaptive',u,[hero(u,'NORTHSTAR / ADAPTIVE WORKSPACE','The next useful step.','A SQL decision reads the current record and working notes; stable editors stay in place.'),filters(u,'visits'),u.stack('work',[u.section('visits','Visit context',[rows(u,'adaptive-jobs','/jobs','job-row')],weight=2),u.section('working','Working notes',[selected_visit(u),u.field('notes','What are you finding?','/state/jobForm/notes','longText'),form_action(u,'save','Save notes','save_job','jobForm',['notes'])],weight=3),u.section('next','Next useful workspace',[u.picker('focus','Workspace selection','/state/controls/focus',[(v,v) for v in ['auto','diagnose','parts','comeback','clarify']]),slot(u,'adaptive-support','/decision/label',{v:'next-'+v for v in ['diagnose','parts','comeback','clarify']},'next-clarify'),u.text('decision-status',bind('/decision/status'),'caption','muted')],tone='accent',weight=3)],'row','lg','tablet')],gap='lg')
    for key,title,path in [('equipment','Pick up the whole story.','/case/equipment'),('parts','Follow the part.','/case/parts'),('schedule','Make the return visit count.','/case/reason')]:
        u=UI();fragment('support-'+key,u,[u.text('heading',title,'title',family='display'),u.text('facts',bind(path)),u.text('history',bind('/case/history'),'caption','muted')])
    u=UI();fragment('case-overview',u,[u.section('parts','The part has a paper trail.',[u.text('copy',bind('/case/parts'))],tone='warm'),u.section('visit','The next visit.',[u.text('readiness',bind('/case/reason'))],tone='cool')],direction='row',gap='md',collapse='tablet')
    u=UI();fragment('case',u,[hero(u,'NORTHSTAR / SHARED WORKSPACE','Harbor rooftop unit','A persistent working file around the replacement, the delivery, and the return visit.'),u.badge('phase',bind('/case/phase'),'warm'),u.text('reason',bind('/case/reason')),u.stack('work',[u.section('file','Working together',[u.field('notes','What are you finding?','/state/caseForm/notes','longText',maxLength=4000),u.field('handoff','Handoff for the return visit','/state/caseForm/handoff','longText',maxLength=4000),form_action(u,'save','Save notes & handoff','save_case','caseForm',['notes','handoff'])],tone='accent',weight=3),u.section('support','Context from Callie',[u.picker('focus','Supporting panel','/state/controls/focus',[(v,v) for v in ['auto','equipment','parts','schedule']]),slot(u,'case-support','/decision/label',{v:'support-'+v for v in ['equipment','parts','schedule']},'support-parts'),u.text('decision-status',bind('/decision/status'),'caption','muted')],weight=2)],'row','lg','tablet'),u.section('tools','Evidence & next steps',[u.picker('mode','Working surface','/state/controls/mode',[('overview','Case evidence'),('receipt','Delivery'),('schedule','Return visit')]),slot(u,'case-tools','/state/controls/mode',{'overview':'case-overview','receipt':'receipt-editor','schedule':'schedule-editor'})],tone='cool'),log(u)],gap='lg')
    # A shared root and fragment registry keep the entry points consistent.
    u=UI();nav=u.stack('navigation',[u.button('page-'+page,label,'page_'+page) for page,label in PAGES.items()],'row','sm',wrap=True)
    page=slot(u,'page','/state/page',{key:key for key in PAGES},'hvac')
    u.stack('root',[nav,page],gap='xl');doc['components']=u.nodes
